import 'package:flutter/material.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:sehatak/core/models/eye/eye_models.dart';
import 'package:sehatak/core/services/eye_service.dart';
const _c=Color(0xFF9C27B0);
class EyeConsultationScreen extends StatefulWidget{const EyeConsultationScreen({super.key});@override State<EyeConsultationScreen> createState()=>_EyeConsultationScreenState();}
class _EyeConsultationScreenState extends State<EyeConsultationScreen>{final _service=EyeService();final _question=TextEditingController();String? _doctorId,_doctorName;bool _saving=false;@override void dispose(){_question.dispose();super.dispose();}Future<void> _submit()async{final user=FirebaseAuth.instance.currentUser;if(user==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('يرجى تسجيل الدخول أولاً')));return;}if(_doctorId==null||_question.text.trim().isEmpty)return;setState(()=>_saving=true);try{await _service.createConsultation(userId:user.uid,userName:user.displayName??'مستخدم',doctorId:_doctorId!,doctorName:_doctorName??'',question:_question.text);if(mounted){_question.clear();ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال الاستشارة')));}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر إرسال الاستشارة: $e')));}finally{if(mounted)setState(()=>_saving=false);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('استشارة عيون')),body:FutureBuilder<List<EyeDoctor>>(future:_service.getTopDoctors(),builder:(context,s){final doctors=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(value:_doctorId,items:doctors.map((d)=>DropdownMenuItem(value:d.id,child:Text(d.name))).toList(),onChanged:(v){final d=doctors.firstWhere((e)=>e.id==v);setState((){_doctorId=v;_doctorName=d.name;});},decoration:const InputDecoration(border:OutlineInputBorder(),labelText:'طبيب العيون')),const SizedBox(height:16),TextField(controller:_question,maxLines:6,decoration:const InputDecoration(border:OutlineInputBorder(),labelText:'سؤالك أو وصف الحالة')),const SizedBox(height:18),SizedBox(width:double.infinity,child:ElevatedButton(onPressed:_saving?null:_submit,style:ElevatedButton.styleFrom(backgroundColor:_c,foregroundColor:Colors.white),child:_saving?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Text('إرسال الاستشارة'))),const SizedBox(height:24),const Text('استشاراتي',style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),if(FirebaseAuth.instance.currentUser!=null)StreamBuilder<List<EyeConsultation>>(stream:_service.streamMyConsultations(FirebaseAuth.instance.currentUser!.uid),builder:(context,s){final items=s.data??[];return Column(children:items.map((d)=>Card(child:ExpansionTile(title:Text(d.question),subtitle:Text(d.status=='answered'?'تم الرد':'قيد الانتظار'),children:[if(d.answer!=null)Padding(padding:const EdgeInsets.all(16),child:Text(d.answer!))])).toList());})]);});}
